//! `.j3ui` components: markup parser (`markup`), J3 text generator (`gen`), and the span map
//! (`map`) that turns errors in the generated text back into `.j3ui` line:col.

pub mod gen;
pub mod icons;
pub mod map;
pub mod markup;
pub mod pass;
pub mod scan;
#[cfg(test)]
mod tests;

use crate::check::CheckError;
use crate::diag::Diagnostic;
use crate::span::{FileId, Span};
pub use gen::{SrcFile, Theme};
use map::SpanMap;

pub struct Generated {
    /// The generated file's name in the loader (what errors say before remapping).
    pub label: String,
    /// Module key, `<package>.ui`.
    pub key: String,
    pub text: String,
    pub map: SpanMap,
    pub files: Vec<SrcFile>,
    pub sections: Vec<(String, usize, usize)>,
}

pub fn label(package: &str) -> String {
    format!("{package}.ui.generated")
}

fn show(file: &SrcFile, e: &markup::UiError) -> String {
    let span = Span { file: FileId(1), start: e.lo as u32, end: e.hi as u32 };
    let mut d = Diagnostic::error(file.path.clone(), span, e.msg.clone());
    if let Some(h) = &e.help {
        d = d.help(h.clone());
    }
    d.render(&[(file.path.clone(), file.text.clone())])
}

/// A generation error with its position kept (the LSP publishes it as a diagnostic).
pub struct BuildErr {
    /// Rendered against the `.j3ui` source.
    pub rendered: String,
    pub path: String,
    pub err: markup::UiError,
}

/// Generate the `<package>.ui` module. The error is rendered against the `.j3ui` source.
pub fn build(files: Vec<SrcFile>, package: &str, theme: Option<Theme>) -> Result<Generated, String> {
    try_build(files, package, theme, &[]).map_err(|e| e.rendered)
}

/// `icons` are the project's own (`icons::load_dir`), found before the Bootstrap set.
pub fn try_build(files: Vec<SrcFile>, package: &str, theme: Option<Theme>, icons: &[icons::Icon]) -> Result<Generated, BuildErr> {
    gen::generate(&files, package, theme.as_ref(), icons)
        .map(|b| Generated { label: label(package), key: format!("{package}.ui"), text: b.text, map: SpanMap { segs: b.segs }, files: files_clone(&files), sections: b.sections })
        .map_err(|e| BuildErr { rendered: show(&files[e.file], &e.err), path: files[e.file].path.clone(), err: e.err })
}

fn files_clone(f: &[SrcFile]) -> Vec<SrcFile> {
    f.iter().map(|x| SrcFile { path: x.path.clone(), name: x.name.clone(), text: x.text.clone() }).collect()
}

impl Generated {
    /// Sources to render remapped errors against.
    pub fn sources(&self) -> Vec<(String, String)> {
        self.files.iter().map(|f| (f.path.clone(), f.text.clone())).collect()
    }

    /// An error in the generated text, moved to the `.j3ui` it came from.
    pub fn remap(&self, e: CheckError) -> CheckError {
        e.map_all(&mut |e| self.remap_one(e))
    }

    fn remap_one(&self, mut e: CheckError) -> CheckError {
        if e.path != self.label {
            return e;
        }
        if let Some(s) = self.map.to_src(e.span.start as usize, e.span.end as usize) {
            e.path = self.files[s.file].path.clone();
            e.span = Span { file: FileId(1), start: s.lo as u32, end: s.hi as u32 };
            if let Some(h) = s.hint {
                e.helps.push(h.to_string());
            }
        }
        e
    }

    /// Generated byte to the `.j3ui` path and 1-based line (runtime aborts). None outside any mapped span.
    pub fn locator(&self) -> std::sync::Arc<dyn Fn(u32) -> Option<(String, usize)> + Send + Sync> {
        let map = SpanMap { segs: self.map.segs.clone() };
        let files: Vec<(String, Vec<usize>)> = self
            .files
            .iter()
            .map(|f| (f.path.clone(), std::iter::once(0).chain(f.text.match_indices('\n').map(|(i, _)| i + 1)).collect()))
            .collect();
        std::sync::Arc::new(move |pos| {
            let s = map.to_src(pos as usize, pos as usize + 1)?;
            let (path, starts) = files.get(s.file)?;
            Some((path.clone(), starts.partition_point(|&x| x <= s.lo)))
        })
    }

    /// A parse error in the generated text (a syntax error in copied J3), rendered at the `.j3ui`.
    pub fn render_parse_error(&self, span: Span, message: &str) -> String {
        let e = self.remap(CheckError::new(self.label.clone(), span, message));
        e.render(&self.sources())
    }
}

/// `j3c dump-ui FILE|DIR`: the generated J3 for a project's components (one component's
/// section when given a file).
pub fn dump(path: &std::path::Path) -> Result<String, String> {
    // A dir below the project root (`j3c dump-ui ui`) walks up to the nearest j3.toml.
    let up = if path.is_dir() && !path.join("j3.toml").is_file() { crate::project::find_toml_up(path) } else { None };
    let m = match up.as_deref().map(crate::project::Manifest::load).transpose()? {
        Some(m) => m,
        None => match crate::project::resolve(path)? {
            crate::project::Input::Project(m) => m,
            _ => return Err("dump-ui needs a project with j3.toml".into()),
        },
    };
    let u = m.ui.clone().ok_or("this project has no [ui] section in j3.toml")?;
    let dir = m.root.join(&u.dir);
    let mut files = Vec::new();
    for f in scan::scan(&dir, &u.dir, &[])? {
        let text = std::fs::read_to_string(&f.path).map_err(|e| format!("read {}: {e}", f.path.display()))?;
        files.push(SrcFile { path: f.shown, name: f.name, text });
    }
    let theme = match &u.theme {
        Some(t) => Some(Theme { path: t.clone(), text: std::fs::read_to_string(m.root.join(t)).map_err(|e| format!("read {t}: {e}"))? }),
        None => None,
    };
    let g = build(files, &m.name, theme)?;
    if path.extension().and_then(|e| e.to_str()) == Some("j3ui") {
        let abs = std::fs::canonicalize(path).map_err(|e| e.to_string())?;
        let name = scan::scan(&dir, &u.dir, &[])?.into_iter().find(|f| std::fs::canonicalize(&f.path).ok().as_ref() == Some(&abs)).map(|f| f.name).ok_or("component not found")?;
        let (_, lo, hi) = g.sections.iter().find(|s| s.0 == name).ok_or("component not found")?;
        return Ok(g.text[*lo..*hi].to_string());
    }
    if up.is_some() {
        // Only the components under `path`; their canonical paths decide, so `.`/symlinks work.
        let under = std::fs::canonicalize(path).map_err(|e| e.to_string())?;
        let mut out = String::new();
        for f in scan::scan(&dir, &u.dir, &[])? {
            if !std::fs::canonicalize(&f.path).is_ok_and(|p| p.starts_with(&under)) {
                continue;
            }
            let (_, lo, hi) = g.sections.iter().find(|s| s.0 == f.name).ok_or("component not found")?;
            out += &g.text[*lo..*hi];
        }
        return Ok(out);
    }
    Ok(g.text)
}
